    const w = (m === "header" || m === "corner") ? [20,20,20,13,14,13] : m === "long-range" ? [14,10,14,18,12,18] : [14,10,14,20,12,20];
    const tot = w.reduce((a,b)=>a+b,0); let r = rng.u()*tot; gz = 5;
    for (let i = 0; i < 6; i++) { r -= w[i]; if (r <= 0) { gz = i; break; } }
