const splitSurname = (n, abbrev) => {
  const full = String(n || "");
  const m = String(abbrev || "").match(/^\p{L}\.\s+(.+)$/u);
  if (m && full.endsWith(m[1])) return { first: full.slice(0, full.length - m[1].length).trim(), last: m[1] };
  return splitFullName(full);
};
const boldSurname = (n, abbrev) => {
  const { first, last } = splitSurname(n, abbrev);
  return first ? <>{first} <b>{last}</b></> : <b>{last}</b>;
};
// THE GOAL MOUTH ITSELF -- turf, net grid, frame and posts. It was written out twice,
// identically, in the resolved-outcome view and in the chance preview; the two differ only
// in what they draw ON it. The geometry is fixed, so it takes no arguments, and the
// constants are shared so a change to the mouth cannot move one view and not the other.

// Narrowest window the app will render in. Below it the app is not shown at all — a layout built
// for width degrades into something misleading rather than merely cramped, and a wrong-looking
// table is worse than an honest refusal.
//
// 1440 is derived, not picked. Every wide tab is two columns of (W - 36 root padding - 16 gap)/2,
// and the live tab's left column splits again into two team cards, each of which splits AGAIN into
// two name columns — so a name cell gets roughly (W - 52)/8 minus the position chip and stamina
// badge. At the old 1000 that left ~47px and every name past eight characters was an ellipsis
// ("K. Higashiy…", "T. Hargre…"). 1440 gives ~95px, which clears the longest names in the roster.
// The page itself caps at 1600, so this is deliberately close to the size the layout was drawn at.
// The layout is built at MIN_APP_WIDTH and scaled to whatever the window gives it, rather than
// refusing anything narrower. MIN_ZOOM is where that stops being a kindness: the smallest labels
// in the app are 8-9px, so 0.75 already renders them at 6-7px and less is past reading.
// Landscape stays a hard requirement — every screen is two side-by-side columns, and a portrait
// window has nowhere to put the second one however far it scales.
const MIN_APP_WIDTH = 1440;
const APP_PAD_X = 18, APP_PAD_Y = 24;
// The design box the layout is drawn in: the header row plus the tallest a tab's panels can be.
// Scaling on BOTH axes is what keeps the aspect fixed — width alone let a short window clip the
// bottom off, which is what the viewport-height panel heights used to paper over by reflowing.
const APP_H = HEADER_H + 32 + PANEL_H + LM_CONTROLS_H;
// What the old canvas holds under the new bars: a tab's panels, the header row gone.
const LEGACY_H = PANEL_H + LM_CONTROLS_H;
// Low enough for an iPad Air in landscape (1180 wide gives 0.79) with room to spare. Under this the
// 8-9px labels stop being readable at all, so the gate takes over rather than pretending.
const MIN_ZOOM = 0.5;
const MIN_WINDOW_W = Math.ceil(MIN_APP_WIDTH * MIN_ZOOM) + APP_PAD_X * 2;
const APP_CSS = `
/* Instant hover tooltips: the native title attribute waits a second and looks like nothing is
   happening, which reads as broken. */
[data-tip] { position: relative; }
[data-tip]:hover::after {
  content: attr(data-tip);
  position: absolute; bottom: calc(100% + 6px); right: 0; z-index: 40;
  background: var(--chrome-bg-dd); color: var(--ui-text);
  border: 1px solid var(--chrome-border); border-radius: 6px;
  padding: 5px 8px; font-size: 9.5px; line-height: 1.4; font-weight: 500;
  white-space: pre; pointer-events: none; box-shadow: 0 4px 14px var(--ui-shadow-3);
}

/* The full-squad list beside the team sheet. Its density is MEASURED, not guessed: SquadFit
   divides the height it actually has by the rows it actually has and writes the three variables
   below, so sixteen players or twenty-four both land inside the column with nothing clipped and
   nothing to scroll. Fixed density classes were tried twice and cut the last man off both times.
   The paddings are inline styles, hence the importants. */
.squad-compact td { padding-top: var(--sq-pad, 2px) !important; padding-bottom: var(--sq-pad, 2px) !important;
                    padding-left: 6px !important; padding-right: 6px !important;
                    font-size: var(--sq-fs, 10.5px) !important; }
.squad-compact th { padding-left: 6px !important; padding-right: 6px !important; }
/* Auto layout with a greedy name column: every other cell is sized by its content and refuses to
   wrap, and the name takes whatever is left. Fixed widths were tried and the seven cells' padding
   ate the column -- the names came out as single letters. */
.squad-compact td, .squad-compact th { white-space: nowrap; }
.squad-compact td { width: 1px; }
.squad-compact td.sq-name { width: 100%; overflow: hidden; text-overflow: ellipsis; }
.squad-compact th { padding-top: 2px !important; padding-bottom: var(--sq-head, 9px) !important; }
.squad-compact tbody tr:first-child td { padding-top: var(--sq-head, 8px) !important; }
.squad-compact img { width: var(--sq-img, 21px) !important; height: var(--sq-img, 21px) !important; }
.squad-compact table { height: 100%; }
.squad-compact tr.sq-div { height: 1px; }

/* Aoboshi One and Agrandir are bundled — see the @font-face blocks in theme.css. These two are not:
   neither ships a file in the repo, so they still come off a CDN and the app falls back to Inter or
   Helvetica Neue wherever it cannot reach one. Drop their files into src/fonts to close that. */
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;600;700&display=swap');
@import url('https://fonts.cdnfonts.com/css/neue-montreal');
*{box-sizing:border-box;margin:0;padding:0;}
/* The window fits the app, not the other way round: .app-body is drawn at MIN_APP_WIDTH and zoomed
   to the window. zoom rather than transform:scale, because it reflows — text stays crisp and
   nothing needs a wrapper sized to undo the transform. --app-zoom is set from the resize handler;
   the 1 here is what first paint uses before it runs. Below MIN_ZOOM this query takes over: the
   <style> tag lives inside .app-root, but style elements apply document-wide regardless of an
   ancestor's display, so hiding the body cannot take these rules down with it. */
:root{--app-zoom:1;}
.app-body{zoom:var(--app-zoom);}
.width-gate{display:none;}
@media(max-width:${MIN_WINDOW_W - 1}px),(orientation:portrait){
  .ux-app{display:none;}
  .width-gate{display:flex;}
}
td,th{vertical-align:middle;}
html,body{overflow:hidden;}
body{font-family:'AviumNumerals','Neue Montreal','Inter','Helvetica Neue',sans-serif;}
::selection{background:var(--chrome-brand-44);color:var(--ui-text);}
::-webkit-scrollbar{width:6px;height:6px;}
::-webkit-scrollbar-track{background:transparent;}
::-webkit-scrollbar-thumb{background:var(--ui-scrollbar);border-radius:10px;}
::-webkit-scrollbar-thumb:hover{background:var(--chrome-muted);}
input,select,textarea{font-family:inherit;transition:border-color 0.2s,box-shadow 0.2s;}
/* Roster rows open a full team panel on click, so they need to read as buttons, not as table
   rows: a brand rail slides in from the left and the chevron lights up under the cursor. */
.cell-link:hover{color:var(--chrome-brand) !important;text-decoration:underline;}
.reg-tab{transition:color 0.12s,border-color 0.12s;}
.reg-tab:hover{color:var(--ui-text) !important;}
.reg-tab:focus-visible,.reg-link:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;border-radius:4px;}
.reg-card{transition:border-color 0.12s,box-shadow 0.12s,transform 0.12s;}
.reg-card:hover{border-color:var(--chrome-muted-66) !important;box-shadow:0 4px 14px var(--ui-shadow-2);transform:translateY(-1px);}
.reg-card:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;}
.reg-link:hover{color:var(--chrome-brand) !important;text-decoration:underline;}
.reg-row{cursor:pointer;}
.reg-banner{transition:transform 0.14s,box-shadow 0.14s,filter 0.14s;box-shadow:0 1px 0 rgba(0,0,0,0.25);}
.reg-banner:hover,.reg-banner:focus-visible{transform:translateY(-1px);box-shadow:0 6px 18px var(--ui-shadow-3);filter:brightness(1.07);}
.reg-banner:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;}
.kit-shirt{transition:transform 0.14s;}
.kit-shirt:hover,.kit-shirt:focus-visible{transform:translateY(-3px);}
.kit-shirt:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:3px;border-radius:6px;}
.kit-shirt .kit-away{opacity:0;transition:opacity 0.18s;}
.kit-shirt:hover .kit-away,.kit-shirt:focus-visible .kit-away{opacity:1;}
.kit-shirt:hover .kit-home,.kit-shirt:focus-visible .kit-home{opacity:0;}
.kit-shirt .kit-home{transition:opacity 0.18s;}
.dyn-stripe{transition:filter 0.12s;}
.dyn-stripe:hover,.dyn-stripe:focus-visible{filter:brightness(1.18);}
.dyn-stripe:focus-visible{outline:2px solid var(--ui-text) !important;outline-offset:1px;}
.atlas-pin{transition:transform 0.12s;}
.atlas-pin:hover,.atlas-pin:focus-visible{transform:translate(-50%, -50%) scale(1.18) !important;}
.atlas-pin:focus-visible{outline:2px solid #fff;outline-offset:2px;border-radius:50%;}
/* A city's panel on the Atlas: its name, then its clubs' crests, at the end of the line from its dot. */
.atlas-city{box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;gap:3px;padding:5px 7px;border-radius:6px;
  background:rgba(8,12,22,0.9);border:1px solid rgba(255,255,255,0.22);box-shadow:0 4px 14px rgba(0,0,0,0.45);}
.atlas-city-name{align-self:stretch;font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;line-height:15px;letter-spacing:0.02em;color:rgba(255,255,255,0.86);white-space:nowrap;overflow:hidden;
  -webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 12px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 12px),transparent);}
.atlas-city-row{display:flex;align-items:center;gap:4px;}
.atlas-city-pin{transition:transform 0.12s;}
.atlas-city-pin:hover,.atlas-city-pin:focus-visible{transform:scale(1.15);}
.atlas-city-pin:focus-visible{outline:2px solid #fff;outline-offset:2px;border-radius:4px;}
/* How many clubs a city's marker stands for, on its corner. */
.atlas-count{position:absolute;right:-0.3em;top:-0.3em;min-width:1.3em;height:1.3em;padding:0 0.22em;border-radius:0.65em;display:flex;align-items:center;justify-content:center;
  background:rgba(10,14,23,0.8);color:#ffffff;font-weight:700;line-height:1;box-shadow:0 1px 2px rgba(0,0,0,0.5);pointer-events:none;}
.reg-row>td{transition:background 0.12s;}
.reg-row:hover>td{background:var(--chrome-muted-22);}
.team-tile{transition:transform 0.12s,border-color 0.12s,box-shadow 0.12s;}
.team-tile:hover{transform:translateY(-2px);border-color:var(--chrome-muted-66) !important;box-shadow:0 4px 14px var(--ui-shadow-2);}
.team-tile:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;}
.lg-card{transition:border-color 0.12s,background 0.12s;}
.lg-card:hover:not(.on){border-color:var(--chrome-muted-66) !important;background:var(--chrome-muted-22) !important;}
.lg-card:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;}
.goal-play:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:-2px;}
/* The fixture hero on the match setup screen. A pick slides its card in from its own end and
   pulses a halo behind the crest; a hover preview only fades; tiles stagger in when the league
   changes. Fill-mode is backwards, not both, on everything that is hovered afterwards: a finished
   animation that keeps hold of transform sits on top of the tile's hover lift for good. */
@keyframes tileIn{from{opacity:0;transform:translateY(8px) scale(0.97)}to{opacity:1;transform:none}}
.tile-in{animation:tileIn 0.32s cubic-bezier(0.22,1,0.36,1) backwards;}
@keyframes regCrest{0%{opacity:0;transform:scale(0.92)}35%{opacity:1;transform:none}65%{opacity:1;transform:none}100%{opacity:0;transform:scale(1.06)}}
.reg-crest{animation:regCrest 0.8s ease-in-out both;}
@keyframes regVeil{0%,65%{opacity:1}100%{opacity:0}}
.reg-veil{animation:regVeil 0.8s ease-in-out both;}
@keyframes pickIn{0%{opacity:0;transform:translateX(var(--pick-dx,-16px)) scale(0.97)}60%{opacity:1;transform:translateX(calc(var(--pick-dx,-16px) * -0.18)) scale(1.01)}100%{opacity:1;transform:none}}
.pick-in{animation:pickIn 0.45s cubic-bezier(0.22,1,0.36,1) backwards;}
@keyframes pvIn{from{opacity:0}to{opacity:1}}
.pv-in{animation:pvIn 0.18s ease-out backwards;}
@keyframes haloPulse{0%{opacity:0;transform:scale(0.4)}35%{opacity:1}100%{opacity:0;transform:scale(1.6)}}
.pick-halo{animation:haloPulse 0.85s ease-out both;}
@keyframes barGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.bar-fill{transform-origin:left;animation:barGrow 0.5s cubic-bezier(0.22,1,0.36,1) backwards;}
.slot-card{transition:border-color 0.18s,box-shadow 0.18s,transform 0.18s;}
.slot-card:not(.on):hover{transform:translateY(-1px);border-color:var(--chrome-muted-66) !important;}
.slot-card:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;}
/* The record editor's controls: a hover on everything that does something, the brand ring on keyboard focus, and a
   disabled look that means it. */
.ed-btn{transition:border-color 0.12s,background 0.12s,color 0.12s;}
.ed-btn:hover:not(:disabled):not(.armed){border-color:var(--chrome-muted-66) !important;color:var(--ui-text) !important;}
.ed-btn-primary{transition:filter 0.12s;}
.ed-btn-primary:hover:not(:disabled){filter:brightness(1.12);}
.ed-btn:focus-visible,.ed-btn-primary:focus-visible,.ed-badge:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:2px;}
.ed-btn:disabled,.ed-btn-primary:disabled{opacity:0.45;cursor:default !important;}
.ed-badge{transition:border-color 0.12s,background 0.12s;}
.ed-badge:hover{border-color:var(--chrome-muted-66) !important;}
.ed-badge[aria-pressed=true]:hover{border-color:var(--chrome-brand) !important;}
.ed-row{transition:border-color 0.12s,background 0.12s;}
.ed-row:hover:not(:disabled){border-color:var(--chrome-muted-66) !important;}
.ed-row[aria-pressed=true]:hover{border-color:var(--chrome-brand) !important;}
.ed-row:focus-visible{outline:2px solid var(--chrome-brand);outline-offset:1px;}
.ed-row:disabled{opacity:0.4;cursor:default !important;}
.vs-swap{transition:transform 0.4s cubic-bezier(0.34,1.56,0.64,1),border-color 0.15s,box-shadow 0.15s;}
.vs-swap:hover:not(:disabled){transform:rotate(180deg);border-color:var(--chrome-brand) !important;box-shadow:0 0 0 4px var(--chrome-brand-22),0 2px 10px var(--ui-shadow-3) !important;}
.vs-swap:active:not(:disabled){transform:rotate(180deg) scale(0.92);}
input[type=number]{-moz-appearance:textfield;}
input[type=number]::-webkit-outer-spin-button,input[type=number]::-webkit-inner-spin-button{-webkit-appearance:none;margin:0;}
input[type=color]{-webkit-appearance:none;appearance:none;padding:0;}
input[type=color]::-webkit-color-swatch-wrapper{padding:0;border-radius:2px;}
input[type=color]::-webkit-color-swatch{border:none;border-radius:2px;}
input[type=color]::-moz-color-swatch{border:none;border-radius:2px;}
input:focus,select:focus,textarea:focus{border-color:var(--chrome-brand) !important;outline:none;box-shadow:0 0 0 3px var(--chrome-brand-20);}
@keyframes fadeIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}
@keyframes slideIn{from{opacity:0;transform:translateX(-8px)}to{opacity:1;transform:translateX(0)}}
@keyframes goalPunch{0%{transform:scale(1)}15%{transform:scale(1.25)}30%{transform:scale(0.95)}50%{transform:scale(1.08)}100%{transform:scale(1)}}
@keyframes goalGlow{0%{text-shadow:0 0 24px var(--ui-text),0 0 48px var(--chrome-brand-44);}50%{text-shadow:0 0 36px var(--ui-text),0 0 72px var(--chrome-brand-44);}100%{text-shadow:none;}}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.4}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes marqueeScroll{0%,20%{transform:translateX(0)}50%,70%{transform:translateX(var(--marquee-dist))}100%{transform:translateX(0)}}
.marquee-name{animation:marqueeScroll 7s ease-in-out infinite;}
/* Fades only the edge a name is actually clipped at. marqueeScroll parks 0-20% at the start and
   50-70% at the end, so the left edge is flush for the first and the right edge for the second;
   both are clipped only while it is travelling. Structurally identical gradients, which is what
   lets the stops interpolate rather than snap.
   The two legs are deliberately not symmetric. Going out, the right fade shrinks over blank space
   the tail has already left, so nobody sees it. Coming back, the LEFT fade shrinks over the first
   characters as they arrive, which is the one retraction that is watched -- so it gets 22% of the
   cycle and three intermediate stops instead of one straight run into the parked frame. */
@keyframes slideFade{0%,18%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 0px,#000 calc(100% - 14px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 0px,#000 calc(100% - 14px),transparent 100%)}34%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 14px,#000 calc(100% - 14px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 14px,#000 calc(100% - 14px),transparent 100%)}50%,68%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 14px,#000 calc(100% - 0px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 14px,#000 calc(100% - 0px),transparent 100%)}78%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 14px,#000 calc(100% - 14px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 14px,#000 calc(100% - 14px),transparent 100%)}86%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 10px,#000 calc(100% - 14px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 10px,#000 calc(100% - 14px),transparent 100%)}93%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 5px,#000 calc(100% - 14px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 5px,#000 calc(100% - 14px),transparent 100%)}100%{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 0px,#000 calc(100% - 14px),transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 0px,#000 calc(100% - 14px),transparent 100%)}}
.slide-fade{animation:slideFade 7s linear infinite;}
.ev-enter{animation:slideIn 0.3s ease;}
.goal-flash{animation:goalPunch 0.6s ease-out, goalGlow 1.2s ease-out;}
.tick-btn{transition:all 0.12s ease;}
.tick-btn:hover{filter:brightness(1.15);transform:translateY(-1px);}
.tick-btn:active{transform:scale(0.97) translateY(0);}
button{transition:all 0.15s ease;}
button:hover:not(:disabled){filter:brightness(1.18);}
.gbtn:hover{filter:brightness(1.05) !important;box-shadow:0 0 12px var(--chrome-brand-88),0 0 4px var(--chrome-brand-66);}
button:disabled{opacity:0.35;cursor:not-allowed;}
details>summary{cursor:pointer;user-select:none;list-style:none;transition:color 0.15s;}
details>summary:hover{color:var(--ui-text) !important;}
details>summary::-webkit-details-marker{display:none;}
details>summary .dta{display:inline-block;margin-right:6px;transition:transform 0.15s;}
details[id^="doc-"]>summary+p{margin-top:12px;}
details[id^="doc-"]>summary+div{margin-top:12px;}
details[open]>summary .dta{transform:rotate(90deg);}
.panel{background:var(--chrome-panel);border:1px solid var(--chrome-border);border-radius:10px;}
select{cursor:pointer;}
input::placeholder{color:var(--chrome-muted);}
table{border-spacing:0;}
@keyframes goalFlash{0%{text-shadow:0 0 24px var(--ui-text),0 0 48px var(--chrome-brand-44);}50%{text-shadow:0 0 36px var(--ui-text),0 0 72px var(--chrome-brand-44);}100%{text-shadow:none;}}
@keyframes cardPop{0%{opacity:0;transform:translateY(8px) scale(0.97)}100%{opacity:1;transform:translateY(0) scale(1)}}
.ev-card{animation:cardPop 0.35s ease-out;}
@keyframes gvLine{from{stroke-dashoffset:var(--gv-len);}to{stroke-dashoffset:0;}}
@keyframes gvBallA{0%{transform:translate(0,0);opacity:0;}8%{opacity:1;}92%{opacity:1;}100%{transform:translate(var(--gv-dx),var(--gv-dy));opacity:0;}}
@keyframes gvBallB{0%{transform:translate(0,0);opacity:0;}10%{opacity:1;}100%{transform:translate(var(--gv-dx),var(--gv-dy));opacity:1;}}
@keyframes gvBallTo{from{transform:translate(0,0);}to{transform:translate(var(--gv-bdx),var(--gv-bdy));}}
@keyframes gvKeep{from{transform:translateX(var(--gv-kdx));}to{transform:translateX(0);}}
@keyframes gvBurst{0%{opacity:0;transform:scale(0.4);}12%{opacity:0.9;}100%{opacity:0;transform:scale(2.4);}}
@keyframes gvDotIn{from{opacity:0;}to{opacity:1;}}
.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--chrome-brand);animation:pulse 1.8s ease-in-out infinite;margin-right:5px;vertical-align:middle;}
@keyframes cardSlam{0%{transform:rotate(-70deg) scale(0.1) translateY(-14px);opacity:0;}55%{transform:rotate(18deg) scale(1.35);opacity:1;}75%{transform:rotate(-6deg) scale(0.92);}100%{transform:rotate(0deg) scale(1) translateY(0);opacity:1;}}
.card-slam{display:inline-block;animation:cardSlam 0.9s cubic-bezier(0.34,1.56,0.64,1) 0.15s both;}
@keyframes sparklePop{0%{transform:scale(0.1) rotate(-40deg);opacity:0;}50%{transform:scale(1.7) rotate(18deg);opacity:1;}70%{transform:scale(0.85) rotate(-6deg);}100%{transform:scale(1) rotate(0deg);opacity:1;}}
.sparkle-pop{display:inline-block;animation:sparklePop 0.85s cubic-bezier(0.34,1.56,0.64,1) 0.15s both;}
@keyframes injuryShake{0%{transform:translateX(0) rotate(0);}10%,30%,50%,70%{transform:translateX(-7px) rotate(-9deg);}20%,40%,60%,80%{transform:translateX(7px) rotate(9deg);}90%{transform:translateX(-3px) rotate(-3deg);}100%{transform:translateX(0) rotate(0);}}
.injury-shake{display:inline-block;animation:injuryShake 0.9s ease-in-out 0.15s both;}
@keyframes subSlideOn{0%{opacity:0;transform:translateX(-32px);}100%{opacity:1;transform:translateX(0);}}
@keyframes subSlideOff{0%{opacity:0;transform:translateX(32px);}100%{opacity:1;transform:translateX(0);}}
.sub-on-line{animation:subSlideOn 0.55s cubic-bezier(0.22,1,0.36,1) both;}
.sub-off-line{animation:subSlideOff 0.55s cubic-bezier(0.22,1,0.36,1) 0.35s both;}
details{border:none;border-bottom:none;}
@media(prefers-reduced-motion:reduce){
  .ev-enter,.goal-flash,.tick-btn,.live-dot,.card-slam,.sparkle-pop,.injury-shake,.sub-on-line,.sub-off-line{animation:none !important;}
  .tile-in,.pick-in,.pv-in,.pick-halo,.bar-fill,.marquee-name,.slide-fade,.reg-crest,.reg-veil{animation:none !important;}
  .gv-anim{animation-duration:0.01ms !important;animation-delay:0ms !important;}
  *{transition-duration:0.01ms !important;}
}
`;

