      const dx = PITCH_L / 2 - mp.bx, dy = ME_HALF_W - mp.by, d = Math.hypot(dx, dy);
      if (d > 0.3) { const k = Math.min(d, ME_PK.pass) / d; mp.bx += dx * k; mp.by += dy * k; }
      mp.bz = 0; mp.bvx = 0; mp.bvy = 0; mp.bvz = 0;
