        <FilterSelect label="Teams" width={180} value={tournTeamF} onChange={setTournTeamF}
          groups={[[null, [["", "All Teams"], ...codes.map(c => { const ct = teamOf(c); return [c, ct ? ct.name : formerName(c)]; })]]]} />
