  useEffect(() => {
    if (!tGroups.length) return;
    setTGroups(gs => {
      let moved = false;
      const next = gs.map(g => {
        const st = recalcStandings(g, tConfig.tiebreakers);
        const before = (g.standings || []).map(r => r.name).join("|");
        if (st.map(r => r.name).join("|") === before) return g;
        moved = true; return { ...g, standings: st };
      });
      return moved ? next : gs;
    });
  }, [tConfig.tiebreakers]);

  // ═══ THE REGISTRY, BY NATION (rebuilt 8 Oct 2026) ════════════════════════════════════════════════
  // The Registry is the nations, each with its national side, its clubs and its leagues, the way the AFA Registry sheet
