  const REG_PANEL = { ...panelBox, padding: 0, marginBottom: 0, overflow: "hidden", height: "100%", minHeight: 0, display: "flex", flexDirection: "column", minWidth: 0 };
  // A heading over a block: the name in sentence case, a count, an action on the right. Tables carry the app's own
